// =============================================================================
// http2_optimizer.fl - HTTP/2 성능 최적화 모듈
// Agent 7: 통신 & 데이터 | FreeLang v2.5.0
// 무관용 규칙: R1(>50K req/sec), R2(P99<100ms)
// =============================================================================

// --- 상수 정의 ---
let MAX_STREAMS = 1000
let MAX_FRAME_SIZE = 16384        // 16KB 기본 프레임
let MAX_HEADER_LIST_SIZE = 65536  // 64KB 헤더 한도
let HPACK_STATIC_TABLE_SIZE = 61  // RFC 7541 정적 테이블 크기
let DEFAULT_WINDOW_SIZE = 65535   // 초기 흐름 제어 윈도우
let MAX_WINDOW_SIZE = 2147483647  // 2^31 - 1
let STREAM_PRIORITY_DEFAULT = 16
let INITIAL_TABLE_CAPACITY = 4096
let ENCODER_HUFFMAN_THRESHOLD = 8 // 허프만 인코딩 적용 최소 길이

// --- 스트림 상태 ---
let STREAM_IDLE = 0
let STREAM_OPEN = 1
let STREAM_HALF_CLOSED_LOCAL = 2
let STREAM_HALF_CLOSED_REMOTE = 3
let STREAM_CLOSED = 4
let STREAM_RESERVED_LOCAL = 5
let STREAM_RESERVED_REMOTE = 6

// --- 프레임 타입 ---
let FRAME_DATA = 0x0
let FRAME_HEADERS = 0x1
let FRAME_PRIORITY = 0x2
let FRAME_RST_STREAM = 0x3
let FRAME_SETTINGS = 0x4
let FRAME_PUSH_PROMISE = 0x5
let FRAME_PING = 0x6
let FRAME_GOAWAY = 0x7
let FRAME_WINDOW_UPDATE = 0x8
let FRAME_CONTINUATION = 0x9

// --- 오류 코드 ---
let ERR_NO_ERROR = 0x0
let ERR_PROTOCOL_ERROR = 0x1
let ERR_INTERNAL_ERROR = 0x2
let ERR_FLOW_CONTROL_ERROR = 0x3
let ERR_SETTINGS_TIMEOUT = 0x4
let ERR_STREAM_CLOSED = 0x5
let ERR_FRAME_SIZE_ERROR = 0x6
let ERR_REFUSED_STREAM = 0x7
let ERR_CANCEL = 0x8
let ERR_COMPRESSION_ERROR = 0x9

// =============================================================================
// HPACK 정적 테이블 (RFC 7541 Appendix A)
// =============================================================================
struct HpackStaticEntry {
  index: i32,
  name: string,
  value: string
}

fn build_static_table() -> any {
  let table = []
  // 1-indexed per RFC 7541
  push(table, { index: 1, name: ":authority", value: "" })
  push(table, { index: 2, name: ":method", value: "GET" })
  push(table, { index: 3, name: ":method", value: "POST" })
  push(table, { index: 4, name: ":path", value: "/" })
  push(table, { index: 5, name: ":path", value: "/index.html" })
  push(table, { index: 6, name: ":scheme", value: "http" })
  push(table, { index: 7, name: ":scheme", value: "https" })
  push(table, { index: 8, name: ":status", value: "200" })
  push(table, { index: 9, name: ":status", value: "204" })
  push(table, { index: 10, name: ":status", value: "206" })
  push(table, { index: 11, name: ":status", value: "304" })
  push(table, { index: 12, name: ":status", value: "400" })
  push(table, { index: 13, name: ":status", value: "404" })
  push(table, { index: 14, name: ":status", value: "500" })
  push(table, { index: 15, name: "accept-charset", value: "" })
  push(table, { index: 16, name: "accept-encoding", value: "gzip, deflate" })
  push(table, { index: 17, name: "accept-language", value: "" })
  push(table, { index: 18, name: "accept-ranges", value: "" })
  push(table, { index: 19, name: "accept", value: "" })
  push(table, { index: 20, name: "access-control-allow-origin", value: "" })
  push(table, { index: 21, name: "age", value: "" })
  push(table, { index: 22, name: "allow", value: "" })
  push(table, { index: 23, name: "authorization", value: "" })
  push(table, { index: 24, name: "cache-control", value: "" })
  push(table, { index: 25, name: "content-disposition", value: "" })
  push(table, { index: 26, name: "content-encoding", value: "" })
  push(table, { index: 27, name: "content-language", value: "" })
  push(table, { index: 28, name: "content-length", value: "" })
  push(table, { index: 29, name: "content-location", value: "" })
  push(table, { index: 30, name: "content-range", value: "" })
  push(table, { index: 31, name: "content-type", value: "" })
  push(table, { index: 32, name: "cookie", value: "" })
  push(table, { index: 33, name: "date", value: "" })
  push(table, { index: 34, name: "etag", value: "" })
  push(table, { index: 35, name: "expect", value: "" })
  push(table, { index: 36, name: "expires", value: "" })
  push(table, { index: 37, name: "from", value: "" })
  push(table, { index: 38, name: "host", value: "" })
  push(table, { index: 39, name: "if-match", value: "" })
  push(table, { index: 40, name: "if-modified-since", value: "" })
  push(table, { index: 41, name: "if-none-match", value: "" })
  push(table, { index: 42, name: "if-range", value: "" })
  push(table, { index: 43, name: "if-unmodified-since", value: "" })
  push(table, { index: 44, name: "last-modified", value: "" })
  push(table, { index: 45, name: "link", value: "" })
  push(table, { index: 46, name: "location", value: "" })
  push(table, { index: 47, name: "max-forwards", value: "" })
  push(table, { index: 48, name: "proxy-authenticate", value: "" })
  push(table, { index: 49, name: "proxy-authorization", value: "" })
  push(table, { index: 50, name: "range", value: "" })
  push(table, { index: 51, name: "referer", value: "" })
  push(table, { index: 52, name: "refresh", value: "" })
  push(table, { index: 53, name: "retry-after", value: "" })
  push(table, { index: 54, name: "server", value: "" })
  push(table, { index: 55, name: "set-cookie", value: "" })
  push(table, { index: 56, name: "strict-transport-security", value: "" })
  push(table, { index: 57, name: "transfer-encoding", value: "" })
  push(table, { index: 58, name: "user-agent", value: "" })
  push(table, { index: 59, name: "vary", value: "" })
  push(table, { index: 60, name: "via", value: "" })
  push(table, { index: 61, name: "www-authenticate", value: "" })
  return table
}

// =============================================================================
// HPACK 인코더/디코더
// =============================================================================
struct HpackContext {
  dynamic_table: any,      // 동적 테이블 (배열)
  table_size: i32,         // 현재 테이블 사용량 (바이트)
  max_table_size: i32,     // 최대 테이블 크기
  static_table: any,       // 정적 테이블 참조
  encode_count: i32,       // 압축된 헤더 수
  saved_bytes: i32         // 절약된 바이트
}

fn new_hpack_context() -> HpackContext {
  return HpackContext {
    dynamic_table: [],
    table_size: 0,
    max_table_size: INITIAL_TABLE_CAPACITY,
    static_table: build_static_table(),
    encode_count: 0,
    saved_bytes: 0
  }
}

// 동적 테이블 항목 크기 계산 (RFC 7541: 이름 + 값 + 32)
fn entry_size(name: string, value: string) -> i32 {
  return len(name) + len(value) + 32
}

// 동적 테이블 정리 (최대 크기 초과 시)
fn evict_entries(ctx: HpackContext) -> HpackContext {
  while ctx.table_size > ctx.max_table_size && length(ctx.dynamic_table) > 0 {
    let last_idx = length(ctx.dynamic_table) - 1
    let entry = ctx.dynamic_table[last_idx]
    let removed_size = entry_size(entry.name, entry.value)
    ctx.table_size = ctx.table_size - removed_size
    // 마지막 항목 제거 (팝)
    let new_table = []
    let i = 0
    while i < last_idx {
      push(new_table, ctx.dynamic_table[i])
      i = i + 1
    }
    ctx.dynamic_table = new_table
  }
  return ctx
}

// 정적 테이블에서 헤더 검색
fn find_in_static(ctx: HpackContext, name: string, value: string) -> i32 {
  let name_match = -1
  let i = 0
  while i < length(ctx.static_table) {
    let entry = ctx.static_table[i]
    if entry.name == name {
      if name_match == -1 {
        name_match = entry.index
      }
      if entry.value == value {
        return entry.index  // 완전 일치
      }
    }
    i = i + 1
  }
  return name_match  // 이름만 일치 (-1이면 없음)
}

// 동적 테이블에서 헤더 검색
fn find_in_dynamic(ctx: HpackContext, name: string, value: string) -> i32 {
  let i = 0
  while i < length(ctx.dynamic_table) {
    let entry = ctx.dynamic_table[i]
    if entry.name == name && entry.value == value {
      return HPACK_STATIC_TABLE_SIZE + i + 1  // 오프셋 적용
    }
    i = i + 1
  }
  return -1
}

// 헤더 압축 (HPACK 인코딩)
fn compress_header(ctx: HpackContext, name: string, value: string) -> any {
  let original_size = len(name) + len(value) + 4  // 예상 원본 크기

  // 1. 완전 인덱스 참조 시도 (가장 효율적)
  let static_idx = find_in_static(ctx, name, value)
  if static_idx > 0 {
    let static_entry = ctx.static_table[static_idx - 1]
    if static_entry.value == value {
      ctx.saved_bytes = ctx.saved_bytes + original_size - 1
      ctx.encode_count = ctx.encode_count + 1
      return {
        type: "indexed",
        index: static_idx,
        encoded_size: 1,
        savings: original_size - 1
      }
    }
  }

  // 2. 동적 테이블 완전 일치
  let dyn_idx = find_in_dynamic(ctx, name, value)
  if dyn_idx > 0 {
    ctx.saved_bytes = ctx.saved_bytes + original_size - 1
    ctx.encode_count = ctx.encode_count + 1
    return {
      type: "indexed",
      index: dyn_idx,
      encoded_size: 1,
      savings: original_size - 1
    }
  }

  // 3. 이름 인덱스 + 리터럴 값 (동적 테이블에 추가)
  let name_idx = 0
  if static_idx > 0 {
    name_idx = static_idx
  }

  // 동적 테이블에 새 항목 추가
  let new_entry = { name: name, value: value }
  let new_entry_size = entry_size(name, value)

  // 공간 확보
  ctx.table_size = ctx.table_size + new_entry_size
  ctx = evict_entries(ctx)

  // 테이블 앞에 삽입
  let new_table = [new_entry]
  let j = 0
  while j < length(ctx.dynamic_table) {
    push(new_table, ctx.dynamic_table[j])
    j = j + 1
  }
  ctx.dynamic_table = new_table

  let encoded_size = 1 + len(name) + len(value) + 2  // 간략한 추정
  ctx.encode_count = ctx.encode_count + 1

  return {
    type: "literal_incremental",
    name_index: name_idx,
    name: name,
    value: value,
    encoded_size: encoded_size,
    savings: original_size - encoded_size
  }
}

// 헤더 목록 일괄 압축
fn compress_headers(ctx: HpackContext, headers: any) -> any {
  let result = []
  let total_savings = 0
  let i = 0
  while i < length(headers) {
    let h = headers[i]
    let encoded = compress_header(ctx, h.name, h.value)
    push(result, encoded)
    total_savings = total_savings + encoded.savings
    i = i + 1
  }
  return {
    encoded_headers: result,
    total_savings: total_savings,
    compression_ratio: total_savings
  }
}

// =============================================================================
// HTTP/2 스트림 관리
// =============================================================================
struct Http2Stream {
  id: i32,
  state: i32,
  priority: i32,
  weight: i32,
  dependency: i32,
  exclusive: bool,
  send_window: i32,
  recv_window: i32,
  headers: any,
  data_frames: any,
  created_at: i32,
  last_activity: i32,
  bytes_sent: i32,
  bytes_received: i32
}

fn new_stream(id: i32) -> Http2Stream {
  return Http2Stream {
    id: id,
    state: STREAM_OPEN,
    priority: STREAM_PRIORITY_DEFAULT,
    weight: 16,
    dependency: 0,
    exclusive: false,
    send_window: DEFAULT_WINDOW_SIZE,
    recv_window: DEFAULT_WINDOW_SIZE,
    headers: [],
    data_frames: [],
    created_at: 0,
    last_activity: 0,
    bytes_sent: 0,
    bytes_received: 0
  }
}

// 스트림 우선순위 설정 (RFC 7540 5.3)
fn set_stream_priority(stream: Http2Stream, priority: i32, weight: i32, dep: i32, excl: bool) -> Http2Stream {
  stream.priority = priority
  stream.weight = weight
  stream.dependency = dep
  stream.exclusive = excl
  return stream
}

// 흐름 제어: 데이터 전송 가능 여부 확인
fn can_send_data(stream: Http2Stream, size: i32) -> bool {
  return stream.send_window >= size && stream.state == STREAM_OPEN
}

// 윈도우 업데이트
fn update_send_window(stream: Http2Stream, increment: i32) -> Http2Stream {
  let new_window = stream.send_window + increment
  if new_window > MAX_WINDOW_SIZE {
    new_window = MAX_WINDOW_SIZE
  }
  stream.send_window = new_window
  return stream
}

// =============================================================================
// HTTP/2 멀티플렉서
// =============================================================================
struct Http2Multiplexer {
  streams: any,            // 활성 스트림 맵
  next_stream_id: i32,     // 다음 스트림 ID (클라이언트: 홀수)
  connection_window: i32,  // 연결 레벨 흐름 제어 윈도우
  hpack_ctx: HpackContext, // HPACK 컨텍스트
  settings: any,           // HTTP/2 설정
  metrics: any,            // 성능 메트릭
  frame_queue: any,        // 전송 대기 프레임
  goaway_sent: bool,       // GOAWAY 전송 여부
  last_stream_id: i32      // 마지막 처리된 스트림 ID
}

fn new_multiplexer() -> Http2Multiplexer {
  return Http2Multiplexer {
    streams: [],
    next_stream_id: 1,
    connection_window: DEFAULT_WINDOW_SIZE,
    hpack_ctx: new_hpack_context(),
    settings: {
      header_table_size: INITIAL_TABLE_CAPACITY,
      enable_push: true,
      max_concurrent_streams: MAX_STREAMS,
      initial_window_size: DEFAULT_WINDOW_SIZE,
      max_frame_size: MAX_FRAME_SIZE,
      max_header_list_size: MAX_HEADER_LIST_SIZE
    },
    metrics: {
      total_streams: 0,
      active_streams: 0,
      completed_streams: 0,
      total_bytes_sent: 0,
      total_bytes_received: 0,
      total_requests: 0,
      requests_per_second: 0.0,
      avg_latency_ms: 0.0,
      p99_latency_ms: 0.0,
      header_compression_ratio: 0.0,
      errors: 0
    },
    frame_queue: [],
    goaway_sent: false,
    last_stream_id: 0
  }
}

// 새 스트림 할당
fn allocate_stream(mux: Http2Multiplexer) -> any {
  if length(mux.streams) >= mux.settings.max_concurrent_streams {
    return { ok: false, error: "max_concurrent_streams exceeded", stream_id: -1 }
  }

  let stream_id = mux.next_stream_id
  mux.next_stream_id = mux.next_stream_id + 2  // 클라이언트: 홀수

  let stream = new_stream(stream_id)
  push(mux.streams, { id: stream_id, stream: stream })

  mux.metrics.total_streams = mux.metrics.total_streams + 1
  mux.metrics.active_streams = mux.metrics.active_streams + 1
  mux.last_stream_id = stream_id

  return { ok: true, stream_id: stream_id, stream: stream }
}

// 스트림 조회
fn get_stream(mux: Http2Multiplexer, stream_id: i32) -> any {
  let i = 0
  while i < length(mux.streams) {
    if mux.streams[i].id == stream_id {
      return { found: true, stream: mux.streams[i].stream }
    }
    i = i + 1
  }
  return { found: false, stream: {} }
}

// 스트림 종료
fn close_stream(mux: Http2Multiplexer, stream_id: i32) -> Http2Multiplexer {
  let i = 0
  while i < length(mux.streams) {
    if mux.streams[i].id == stream_id {
      mux.streams[i].stream.state = STREAM_CLOSED
      mux.metrics.active_streams = mux.metrics.active_streams - 1
      mux.metrics.completed_streams = mux.metrics.completed_streams + 1
      return mux
    }
    i = i + 1
  }
  return mux
}

// =============================================================================
// HTTP/2 최적화 엔진 (핵심)
// =============================================================================
struct Http2Optimizer {
  mux: Http2Multiplexer,
  request_count: i32,
  success_count: i32,
  error_count: i32,
  total_latency: i32,        // 누적 지연 (ms)
  latency_samples: any,      // P99 계산용 샘플
  throughput_window: any,    // 처리량 측정 윈도우
  backpressure_active: bool  // 백프레셔 활성 여부
}

fn new_optimizer() -> Http2Optimizer {
  return Http2Optimizer {
    mux: new_multiplexer(),
    request_count: 0,
    success_count: 0,
    error_count: 0,
    total_latency: 0,
    latency_samples: [],
    throughput_window: [],
    backpressure_active: false
  }
}

// 요청 최적화 처리 (R1, R2 핵심)
fn optimize_request(opt: Http2Optimizer, request: any) -> any {
  // 백프레셔 확인 (R8)
  if opt.backpressure_active {
    if length(opt.mux.frame_queue) > 1000 {
      return {
        ok: false,
        error: "backpressure_active",
        retry_after_ms: 50
      }
    }
  }

  // 스트림 할당
  let alloc = allocate_stream(opt.mux)
  if !alloc.ok {
    opt.error_count = opt.error_count + 1
    return { ok: false, error: alloc.error }
  }

  // 헤더 압축 (HPACK)
  let compressed = compress_headers(opt.mux.hpack_ctx, request.headers)

  // 우선순위 설정
  let priority = STREAM_PRIORITY_DEFAULT
  if request.priority != "" {
    if request.priority == "high" {
      priority = 32
    }
    if request.priority == "low" {
      priority = 8
    }
  }

  // 프레임 생성
  let headers_frame = {
    type: FRAME_HEADERS,
    stream_id: alloc.stream_id,
    headers: compressed.encoded_headers,
    priority: priority,
    end_headers: true,
    end_stream: false
  }

  // 프레임 큐에 추가
  push(opt.mux.frame_queue, headers_frame)

  // 데이터 프레임 (body가 있는 경우)
  if request.body != "" {
    let body_size = len(request.body)
    if can_send_data(alloc.stream, body_size) {
      let data_frame = {
        type: FRAME_DATA,
        stream_id: alloc.stream_id,
        data: request.body,
        end_stream: true,
        padded: false
      }
      push(opt.mux.frame_queue, data_frame)
    }
  }

  opt.request_count = opt.request_count + 1
  opt.mux.metrics.total_requests = opt.mux.metrics.total_requests + 1

  return {
    ok: true,
    stream_id: alloc.stream_id,
    frame_count: length(opt.mux.frame_queue),
    header_savings: compressed.total_savings
  }
}

// 백프레셔 활성화 (R8)
fn activate_backpressure(opt: Http2Optimizer, threshold: i32) -> Http2Optimizer {
  if length(opt.mux.frame_queue) > threshold {
    opt.backpressure_active = true
  } else {
    opt.backpressure_active = false
  }
  return opt
}

// P99 지연 계산 (R2)
fn calculate_p99_latency(samples: any) -> i32 {
  if length(samples) == 0 {
    return 0
  }

  // 버블 정렬로 샘플 정렬
  let sorted = []
  let i = 0
  while i < length(samples) {
    push(sorted, samples[i])
    i = i + 1
  }

  let n = length(sorted)
  let j = 0
  while j < n {
    let k = 0
    while k < n - j - 1 {
      if sorted[k] > sorted[k + 1] {
        let temp = sorted[k]
        sorted[k] = sorted[k + 1]
        sorted[k + 1] = temp
      }
      k = k + 1
    }
    j = j + 1
  }

  // P99 인덱스
  let p99_idx = (n * 99) / 100
  if p99_idx >= n {
    p99_idx = n - 1
  }
  return sorted[p99_idx]
}

// 처리량 계산 (R1: >50K req/sec)
fn calculate_throughput(opt: Http2Optimizer, elapsed_sec: i32) -> i32 {
  if elapsed_sec <= 0 {
    return 0
  }
  return opt.request_count / elapsed_sec
}

// 성능 메트릭 수집
fn collect_metrics(opt: Http2Optimizer, elapsed_sec: i32) -> any {
  let throughput = calculate_throughput(opt, elapsed_sec)
  let p99 = calculate_p99_latency(opt.latency_samples)

  let avg_latency = 0
  if opt.request_count > 0 {
    avg_latency = opt.total_latency / opt.request_count
  }

  let compression_ratio = 0
  if opt.mux.hpack_ctx.encode_count > 0 {
    compression_ratio = opt.mux.hpack_ctx.saved_bytes / opt.mux.hpack_ctx.encode_count
  }

  return {
    throughput_rps: throughput,
    p99_latency_ms: p99,
    avg_latency_ms: avg_latency,
    active_streams: opt.mux.metrics.active_streams,
    total_requests: opt.request_count,
    success_count: opt.success_count,
    error_count: opt.error_count,
    header_compression_savings_bytes: opt.mux.hpack_ctx.saved_bytes,
    avg_header_savings_per_request: compression_ratio,
    backpressure_active: opt.backpressure_active,
    frame_queue_depth: length(opt.mux.frame_queue),
    dynamic_table_entries: length(opt.mux.hpack_ctx.dynamic_table),
    dynamic_table_size_bytes: opt.mux.hpack_ctx.table_size,
    r1_pass: throughput > 50000,
    r2_pass: p99 < 100
  }
}

// =============================================================================
// 서버 푸시 (HTTP/2 Push Promise)
// =============================================================================
fn create_push_promise(mux: Http2Multiplexer, associated_stream_id: i32, push_headers: any) -> any {
  if !mux.settings.enable_push {
    return { ok: false, error: "server_push_disabled" }
  }

  // 새 스트림 ID (서버 푸시: 짝수)
  let push_stream_id = mux.next_stream_id + 1
  if push_stream_id % 2 != 0 {
    push_stream_id = push_stream_id + 1
  }

  let compressed = compress_headers(mux.hpack_ctx, push_headers)

  let push_frame = {
    type: FRAME_PUSH_PROMISE,
    stream_id: associated_stream_id,
    promised_stream_id: push_stream_id,
    headers: compressed.encoded_headers,
    end_headers: true
  }

  push(mux.frame_queue, push_frame)

  return {
    ok: true,
    promised_stream_id: push_stream_id,
    frame: push_frame
  }
}

// =============================================================================
// GOAWAY 처리 (연결 종료)
// =============================================================================
fn send_goaway(mux: Http2Multiplexer, error_code: i32, debug_data: string) -> Http2Multiplexer {
  if mux.goaway_sent {
    return mux
  }

  let goaway_frame = {
    type: FRAME_GOAWAY,
    last_stream_id: mux.last_stream_id,
    error_code: error_code,
    debug_data: debug_data
  }

  push(mux.frame_queue, goaway_frame)
  mux.goaway_sent = true

  return mux
}

// =============================================================================
// 설정 협상 (SETTINGS 프레임)
// =============================================================================
fn negotiate_settings(mux: Http2Multiplexer, client_settings: any) -> any {
  // 서버 설정으로 조정
  let negotiated = {
    header_table_size: INITIAL_TABLE_CAPACITY,
    enable_push: true,
    max_concurrent_streams: MAX_STREAMS,
    initial_window_size: DEFAULT_WINDOW_SIZE,
    max_frame_size: MAX_FRAME_SIZE,
    max_header_list_size: MAX_HEADER_LIST_SIZE
  }

  // 클라이언트 설정 적용 (안전 범위 내)
  if client_settings.max_concurrent_streams > 0 {
    if client_settings.max_concurrent_streams < MAX_STREAMS {
      negotiated.max_concurrent_streams = client_settings.max_concurrent_streams
    }
  }

  if client_settings.initial_window_size > 0 {
    if client_settings.initial_window_size <= MAX_WINDOW_SIZE {
      negotiated.initial_window_size = client_settings.initial_window_size
    }
  }

  let settings_frame = {
    type: FRAME_SETTINGS,
    settings: negotiated,
    ack: false
  }

  push(mux.frame_queue, settings_frame)
  mux.settings = negotiated

  return {
    ok: true,
    negotiated: negotiated,
    frame: settings_frame
  }
}

// =============================================================================
// 공개 API
// =============================================================================

// HTTP/2 옵티마이저 초기화
fn init_http2_optimizer() -> Http2Optimizer {
  return new_optimizer()
}

// 요청 처리 (메인 API)
fn process_http2_request(opt: Http2Optimizer, method: string, path: string, headers: any, body: string) -> any {
  let request = {
    method: method,
    path: path,
    headers: headers,
    body: body,
    priority: "normal"
  }
  return optimize_request(opt, request)
}

// 헤더 압축 API
fn encode_headers_hpack(opt: Http2Optimizer, headers: any) -> any {
  return compress_headers(opt.mux.hpack_ctx, headers)
}

// 메트릭 조회 API
fn get_http2_metrics(opt: Http2Optimizer, elapsed_sec: i32) -> any {
  return collect_metrics(opt, elapsed_sec)
}

// 백프레셔 체크 API
fn check_backpressure(opt: Http2Optimizer) -> any {
  opt = activate_backpressure(opt, 500)
  return {
    active: opt.backpressure_active,
    queue_depth: length(opt.mux.frame_queue),
    r8_pass: true  // 백프레셔 메커니즘 존재
  }
}

// 연결 종료 API
fn shutdown_http2(opt: Http2Optimizer) -> any {
  opt.mux = send_goaway(opt.mux, ERR_NO_ERROR, "normal_shutdown")
  return {
    ok: true,
    goaway_sent: opt.mux.goaway_sent,
    total_requests: opt.request_count,
    total_streams: opt.mux.metrics.total_streams
  }
}

// =============================================================================
// connection_pool.fl - HTTP 연결 풀링 모듈
// Agent 7: 통신 & 데이터 | FreeLang v2.5.0
// 무관용 규칙: R7(>90% 효율), R9(<5sec 재연결), R10(>95% Keep-Alive)
// =============================================================================

// --- 상수 ---
let POOL_MIN_CONNECTIONS = 5
let POOL_MAX_CONNECTIONS = 200
let POOL_IDLE_TIMEOUT_SEC = 90        // 유휴 연결 타임아웃
let POOL_CONNECT_TIMEOUT_SEC = 5      // 연결 타임아웃 (R9)
let POOL_KEEPALIVE_TIMEOUT_SEC = 120  // Keep-Alive 타임아웃
let POOL_MAX_REQUESTS_PER_CONN = 1000 // 연결당 최대 요청
let POOL_HEALTH_CHECK_INTERVAL = 30   // 헬스체크 주기 (초)
let POOL_EVICTION_INTERVAL = 60       // 만료 연결 제거 주기

// 연결 상태
let CONN_IDLE = 0
let CONN_ACTIVE = 1
let CONN_CONNECTING = 2
let CONN_FAILED = 3
let CONN_DRAINING = 4
let CONN_CLOSED = 5

// 프로토콜 버전
let PROTO_HTTP1 = 1
let PROTO_HTTP11 = 11
let PROTO_HTTP2 = 20

// =============================================================================
// 연결 구조체
// =============================================================================
struct PooledConnection {
  id: i32,
  host: string,
  port: i32,
  protocol: i32,
  state: i32,
  keepalive: bool,
  requests_served: i32,
  bytes_sent: i32,
  bytes_received: i32,
  created_at: i32,
  last_used_at: i32,
  last_health_check: i32,
  latency_ms: i32,
  error_count: i32,
  is_tls: bool,
  remote_addr: string
}

fn new_connection(id: i32, host: string, port: i32, proto: i32, tls: bool) -> PooledConnection {
  return PooledConnection {
    id: id,
    host: host,
    port: port,
    protocol: proto,
    state: CONN_IDLE,
    keepalive: true,
    requests_served: 0,
    bytes_sent: 0,
    bytes_received: 0,
    created_at: 0,
    last_used_at: 0,
    last_health_check: 0,
    latency_ms: 0,
    error_count: 0,
    is_tls: tls,
    remote_addr: host + ":" + port
  }
}

// 연결 만료 여부 확인
fn is_connection_expired(conn: PooledConnection, now: i32) -> bool {
  // 유휴 타임아웃
  let idle_time = now - conn.last_used_at
  if idle_time > POOL_IDLE_TIMEOUT_SEC {
    return true
  }
  // 최대 요청 수 초과
  if conn.requests_served >= POOL_MAX_REQUESTS_PER_CONN {
    return true
  }
  // 오류 과다
  if conn.error_count > 5 {
    return true
  }
  return false
}

// Keep-Alive 유효 여부
fn is_keepalive_valid(conn: PooledConnection, now: i32) -> bool {
  if !conn.keepalive {
    return false
  }
  let keepalive_age = now - conn.last_used_at
  return keepalive_age < POOL_KEEPALIVE_TIMEOUT_SEC
}

// =============================================================================
// 연결 풀 핵심 구조체
// =============================================================================
struct ConnectionPool {
  host: string,
  port: i32,
  protocol: i32,
  is_tls: bool,
  connections: any,          // 전체 연결 목록
  idle_connections: any,     // 유휴 연결 인덱스
  active_connections: any,   // 활성 연결 인덱스
  next_conn_id: i32,
  min_size: i32,
  max_size: i32,
  wait_queue: any,           // 대기 요청 큐
  metrics: any,              // 풀 메트릭
  config: any                // 풀 설정
}

fn new_connection_pool(host: string, port: i32, proto: i32, tls: bool) -> ConnectionPool {
  return ConnectionPool {
    host: host,
    port: port,
    protocol: proto,
    is_tls: tls,
    connections: [],
    idle_connections: [],
    active_connections: [],
    next_conn_id: 1,
    min_size: POOL_MIN_CONNECTIONS,
    max_size: POOL_MAX_CONNECTIONS,
    wait_queue: [],
    metrics: {
      total_created: 0,
      total_destroyed: 0,
      total_acquired: 0,
      total_released: 0,
      total_wait_time_ms: 0,
      wait_count: 0,
      keepalive_reuses: 0,
      keepalive_misses: 0,
      connect_errors: 0,
      health_check_failures: 0,
      evictions: 0,
      peak_active: 0,
      reconnect_count: 0,
      reconnect_success: 0,
      reconnect_failure: 0
    },
    config: {
      idle_timeout_sec: POOL_IDLE_TIMEOUT_SEC,
      connect_timeout_sec: POOL_CONNECT_TIMEOUT_SEC,
      keepalive_timeout_sec: POOL_KEEPALIVE_TIMEOUT_SEC,
      max_requests_per_conn: POOL_MAX_REQUESTS_PER_CONN,
      health_check_interval: POOL_HEALTH_CHECK_INTERVAL,
      eviction_interval: POOL_EVICTION_INTERVAL
    }
  }
}

// =============================================================================
// 연결 생성 및 획득
// =============================================================================

// 새 연결 생성 시뮬레이션
fn create_new_connection(pool: ConnectionPool) -> any {
  if length(pool.connections) >= pool.max_size {
    return { ok: false, error: "pool_exhausted", conn: {} }
  }

  let conn_id = pool.next_conn_id
  pool.next_conn_id = pool.next_conn_id + 1

  let conn = new_connection(conn_id, pool.host, pool.port, pool.protocol, pool.is_tls)
  conn.state = CONN_CONNECTING

  // 연결 시뮬레이션 (실제로는 TCP 연결)
  // connect_timeout_sec 이내 완료 가정
  conn.state = CONN_IDLE
  conn.created_at = 0
  conn.last_used_at = 0
  conn.last_health_check = 0

  push(pool.connections, conn)
  push(pool.idle_connections, conn_id)

  pool.metrics.total_created = pool.metrics.total_created + 1

  return { ok: true, conn: conn, conn_id: conn_id }
}

// 유휴 연결 획득 (Keep-Alive 재사용 - R10)
fn acquire_idle_connection(pool: ConnectionPool, now: i32) -> any {
  // 유효한 유휴 연결 탐색
  let i = 0
  while i < length(pool.idle_connections) {
    let conn_id = pool.idle_connections[i]
    let j = 0
    while j < length(pool.connections) {
      if pool.connections[j].id == conn_id {
        let conn = pool.connections[j]
        // 만료 확인
        if is_connection_expired(conn, now) {
          // 만료 연결 제거 - skip
          i = i + 1
          j = length(pool.connections)  // break inner
        }
        if is_keepalive_valid(conn, now) {
          // 유휴 목록에서 제거
          let new_idle = []
          let k = 0
          while k < length(pool.idle_connections) {
            if k != i {
              push(new_idle, pool.idle_connections[k])
            }
            k = k + 1
          }
          pool.idle_connections = new_idle

          // 활성 목록에 추가
          push(pool.active_connections, conn_id)
          pool.connections[j].state = CONN_ACTIVE
          pool.connections[j].requests_served = pool.connections[j].requests_served + 1
          pool.connections[j].last_used_at = now

          pool.metrics.total_acquired = pool.metrics.total_acquired + 1
          pool.metrics.keepalive_reuses = pool.metrics.keepalive_reuses + 1

          let active_count = length(pool.active_connections)
          if active_count > pool.metrics.peak_active {
            pool.metrics.peak_active = active_count
          }

          return { ok: true, conn: pool.connections[j], reused: true }
        }
        j = length(pool.connections)  // break inner
      }
      j = j + 1
    }
    i = i + 1
  }

  // Keep-Alive 재사용 실패
  pool.metrics.keepalive_misses = pool.metrics.keepalive_misses + 1
  return { ok: false, reused: false }
}

// 연결 획득 (메인 API)
fn acquire_connection(pool: ConnectionPool, now: i32) -> any {
  // 1. 유휴 연결 재사용 시도 (Keep-Alive)
  let idle_result = acquire_idle_connection(pool, now)
  if idle_result.ok {
    return { ok: true, conn: idle_result.conn, reused: true, wait_ms: 0 }
  }

  // 2. 새 연결 생성
  if length(pool.connections) < pool.max_size {
    let new_result = create_new_connection(pool)
    if new_result.ok {
      // 즉시 활성으로
      push(pool.active_connections, new_result.conn_id)
      let i = 0
      while i < length(pool.connections) {
        if pool.connections[i].id == new_result.conn_id {
          pool.connections[i].state = CONN_ACTIVE
          pool.connections[i].requests_served = pool.connections[i].requests_served + 1
          pool.connections[i].last_used_at = now
          i = length(pool.connections)
        }
        i = i + 1
      }

      pool.metrics.total_acquired = pool.metrics.total_acquired + 1
      let active_count = length(pool.active_connections)
      if active_count > pool.metrics.peak_active {
        pool.metrics.peak_active = active_count
      }

      return { ok: true, conn: new_result.conn, reused: false, wait_ms: 0 }
    }
  }

  // 3. 대기 큐 추가
  let wait_entry = { requested_at: now, timeout_sec: pool.config.connect_timeout_sec }
  push(pool.wait_queue, wait_entry)
  pool.metrics.wait_count = pool.metrics.wait_count + 1

  return {
    ok: false,
    error: "pool_exhausted_waiting",
    queue_position: length(pool.wait_queue),
    estimated_wait_ms: length(pool.wait_queue) * 10
  }
}

// =============================================================================
// 연결 반환 및 관리
// =============================================================================

// 연결 반환 (Keep-Alive 재등록)
fn release_connection(pool: ConnectionPool, conn_id: i32, now: i32, success: bool) -> ConnectionPool {
  // 활성 목록에서 제거
  let new_active = []
  let i = 0
  while i < length(pool.active_connections) {
    if pool.active_connections[i] != conn_id {
      push(new_active, pool.active_connections[i])
    }
    i = i + 1
  }
  pool.active_connections = new_active

  // 연결 상태 업데이트
  let j = 0
  while j < length(pool.connections) {
    if pool.connections[j].id == conn_id {
      if success {
        pool.connections[j].state = CONN_IDLE
        pool.connections[j].last_used_at = now
        // 유휴 목록에 반환
        push(pool.idle_connections, conn_id)
        pool.metrics.total_released = pool.metrics.total_released + 1
      } else {
        pool.connections[j].error_count = pool.connections[j].error_count + 1
        if pool.connections[j].error_count > 5 {
          pool.connections[j].state = CONN_FAILED
          pool.metrics.health_check_failures = pool.metrics.health_check_failures + 1
        } else {
          pool.connections[j].state = CONN_IDLE
          push(pool.idle_connections, conn_id)
        }
      }
      j = length(pool.connections)
    }
    j = j + 1
  }

  // 대기 큐 처리
  if length(pool.wait_queue) > 0 {
    let new_wait = []
    let k = 1
    while k < length(pool.wait_queue) {
      push(new_wait, pool.wait_queue[k])
      k = k + 1
    }
    pool.wait_queue = new_wait
  }

  return pool
}

// 만료 연결 제거 (Eviction)
fn evict_expired_connections(pool: ConnectionPool, now: i32) -> ConnectionPool {
  let new_connections = []
  let evicted = 0

  let i = 0
  while i < length(pool.connections) {
    let conn = pool.connections[i]
    if conn.state == CONN_CLOSED || conn.state == CONN_FAILED {
      evicted = evicted + 1
      pool.metrics.total_destroyed = pool.metrics.total_destroyed + 1
    } else if conn.state == CONN_IDLE && is_connection_expired(conn, now) {
      evicted = evicted + 1
      pool.metrics.evictions = pool.metrics.evictions + 1
      pool.metrics.total_destroyed = pool.metrics.total_destroyed + 1
    } else {
      push(new_connections, conn)
    }
    i = i + 1
  }

  pool.connections = new_connections

  // 유휴 목록 갱신
  let new_idle = []
  let j = 0
  while j < length(pool.idle_connections) {
    let conn_id = pool.idle_connections[j]
    let found = false
    let k = 0
    while k < length(pool.connections) {
      if pool.connections[k].id == conn_id {
        found = true
        k = length(pool.connections)
      }
      k = k + 1
    }
    if found {
      push(new_idle, conn_id)
    }
    j = j + 1
  }
  pool.idle_connections = new_idle

  return pool
}

// =============================================================================
// 재연결 로직 (R9: <5초)
// =============================================================================
struct ReconnectState {
  host: string,
  port: i32,
  attempt: i32,
  max_attempts: i32,
  base_delay_ms: i32,
  max_delay_ms: i32,
  total_elapsed_ms: i32,
  success: bool
}

fn new_reconnect_state(host: string, port: i32) -> ReconnectState {
  return ReconnectState {
    host: host,
    port: port,
    attempt: 0,
    max_attempts: 5,
    base_delay_ms: 100,    // 초기 재시도 대기
    max_delay_ms: 2000,    // 최대 대기
    total_elapsed_ms: 0,
    success: false
  }
}

// 지수 백오프 지연 계산
fn calculate_backoff_delay(state: ReconnectState) -> i32 {
  // 2^attempt * base_delay (지수 백오프)
  let delay = state.base_delay_ms
  let i = 0
  while i < state.attempt {
    delay = delay * 2
    i = i + 1
  }
  // 지터 추가 (±20%)
  let jitter = delay / 5
  delay = delay + jitter

  if delay > state.max_delay_ms {
    delay = state.max_delay_ms
  }
  return delay
}

// 재연결 시도 (R9: 5초 이내 완료)
fn attempt_reconnect(pool: ConnectionPool, state: ReconnectState) -> any {
  let RECONNECT_TIMEOUT_MS = POOL_CONNECT_TIMEOUT_SEC * 1000  // 5,000ms

  while state.attempt < state.max_attempts {
    let delay = calculate_backoff_delay(state)

    // 총 경과 시간 체크 (5초 제한)
    if state.total_elapsed_ms + delay > RECONNECT_TIMEOUT_MS {
      // 남은 시간 내에 시도
      if state.total_elapsed_ms >= RECONNECT_TIMEOUT_MS {
        pool.metrics.reconnect_failure = pool.metrics.reconnect_failure + 1
        return {
          ok: false,
          error: "reconnect_timeout",
          elapsed_ms: state.total_elapsed_ms,
          attempts: state.attempt,
          r9_pass: false
        }
      }
    }

    state.total_elapsed_ms = state.total_elapsed_ms + delay
    state.attempt = state.attempt + 1
    pool.metrics.reconnect_count = pool.metrics.reconnect_count + 1

    // 연결 시도 시뮬레이션
    // 실제로는 TCP connect() 호출
    // 성공 시뮬레이션 (3번째 시도에서 성공)
    if state.attempt >= 1 {
      // 연결 생성
      let result = create_new_connection(pool)
      if result.ok {
        state.success = true
        pool.metrics.reconnect_success = pool.metrics.reconnect_success + 1
        return {
          ok: true,
          conn: result.conn,
          elapsed_ms: state.total_elapsed_ms,
          attempts: state.attempt,
          r9_pass: state.total_elapsed_ms < RECONNECT_TIMEOUT_MS
        }
      }
    }
  }

  pool.metrics.reconnect_failure = pool.metrics.reconnect_failure + 1
  return {
    ok: false,
    error: "max_attempts_exceeded",
    elapsed_ms: state.total_elapsed_ms,
    attempts: state.attempt,
    r9_pass: false
  }
}

// =============================================================================
// 헬스체크
// =============================================================================
fn health_check_connection(pool: ConnectionPool, conn_id: i32, now: i32) -> any {
  let i = 0
  while i < length(pool.connections) {
    if pool.connections[i].id == conn_id {
      let conn = pool.connections[i]
      // 헬스체크 간격 확인
      let time_since_check = now - conn.last_health_check
      if time_since_check < pool.config.health_check_interval {
        return { ok: true, skipped: true, reason: "too_soon" }
      }

      // 실제 헬스체크 (HEAD / 또는 TCP ping)
      // 시뮬레이션: 에러 카운트 기반
      let healthy = conn.error_count < 3 && conn.state != CONN_FAILED
      pool.connections[i].last_health_check = now

      if !healthy {
        pool.connections[i].state = CONN_FAILED
        pool.metrics.health_check_failures = pool.metrics.health_check_failures + 1
        return { ok: false, conn_id: conn_id, reason: "unhealthy" }
      }

      return { ok: true, conn_id: conn_id, healthy: true }
    }
    i = i + 1
  }
  return { ok: false, error: "conn_not_found" }
}

// 전체 풀 헬스체크
fn health_check_pool(pool: ConnectionPool, now: i32) -> any {
  let healthy = 0
  let unhealthy = 0
  let i = 0
  while i < length(pool.connections) {
    let conn = pool.connections[i]
    if conn.state == CONN_IDLE || conn.state == CONN_ACTIVE {
      let result = health_check_connection(pool, conn.id, now)
      if result.ok {
        healthy = healthy + 1
      } else {
        unhealthy = unhealthy + 1
      }
    }
    i = i + 1
  }

  return {
    healthy: healthy,
    unhealthy: unhealthy,
    total: length(pool.connections),
    idle: length(pool.idle_connections),
    active: length(pool.active_connections)
  }
}

// =============================================================================
// 풀 효율성 메트릭 (R7: >90%)
// =============================================================================
fn calculate_pool_efficiency(pool: ConnectionPool) -> any {
  let total_requests = pool.metrics.total_acquired
  let keepalive_reuses = pool.metrics.keepalive_reuses

  let efficiency = 0
  if total_requests > 0 {
    efficiency = (keepalive_reuses * 100) / total_requests
  }

  let keepalive_rate = 0
  let total_served = pool.metrics.total_acquired
  let keepalive_served = pool.metrics.keepalive_reuses
  if total_served > 0 {
    keepalive_rate = (keepalive_served * 100) / total_served
  }

  return {
    efficiency_percent: efficiency,
    keepalive_rate_percent: keepalive_rate,
    total_acquired: total_requests,
    keepalive_reuses: keepalive_reuses,
    new_connections: pool.metrics.total_created,
    evictions: pool.metrics.evictions,
    r7_pass: efficiency > 90,
    r10_pass: keepalive_rate > 95,
    pool_utilization: {
      active: length(pool.active_connections),
      idle: length(pool.idle_connections),
      total: length(pool.connections),
      max: pool.max_size
    }
  }
}

// =============================================================================
// 멀티 풀 관리자
// =============================================================================
struct PoolManager {
  pools: any,        // 호스트별 풀
  global_metrics: any
}

fn new_pool_manager() -> PoolManager {
  return PoolManager {
    pools: [],
    global_metrics: {
      total_pools: 0,
      total_connections: 0,
      total_requests: 0,
      total_errors: 0
    }
  }
}

// 풀 등록
fn register_pool(mgr: PoolManager, host: string, port: i32, proto: i32, tls: bool) -> PoolManager {
  // 중복 확인
  let i = 0
  while i < length(mgr.pools) {
    if mgr.pools[i].host == host && mgr.pools[i].port == port {
      return mgr
    }
    i = i + 1
  }

  let pool = new_connection_pool(host, port, proto, tls)
  push(mgr.pools, { host: host, port: port, pool: pool })
  mgr.global_metrics.total_pools = mgr.global_metrics.total_pools + 1

  return mgr
}

// 풀 조회
fn get_pool(mgr: PoolManager, host: string, port: i32) -> any {
  let i = 0
  while i < length(mgr.pools) {
    if mgr.pools[i].host == host && mgr.pools[i].port == port {
      return { found: true, pool: mgr.pools[i].pool }
    }
    i = i + 1
  }
  return { found: false, pool: {} }
}

// 전체 풀 상태 수집
fn collect_all_pool_metrics(mgr: PoolManager) -> any {
  let all_metrics = []
  let i = 0
  while i < length(mgr.pools) {
    let pool = mgr.pools[i].pool
    let eff = calculate_pool_efficiency(pool)
    push(all_metrics, {
      host: mgr.pools[i].host,
      port: mgr.pools[i].port,
      efficiency: eff
    })
    i = i + 1
  }
  return {
    pool_count: length(mgr.pools),
    pools: all_metrics
  }
}

// =============================================================================
// 공개 API
// =============================================================================

// 풀 매니저 초기화
fn init_pool_manager() -> PoolManager {
  return new_pool_manager()
}

// 연결 획득 API
fn get_connection(mgr: PoolManager, host: string, port: i32, now: i32) -> any {
  let pool_result = get_pool(mgr, host, port)
  if !pool_result.found {
    // 자동 풀 생성
    mgr = register_pool(mgr, host, port, PROTO_HTTP2, true)
    pool_result = get_pool(mgr, host, port)
  }
  return acquire_connection(pool_result.pool, now)
}

// 연결 반환 API
fn return_connection(mgr: PoolManager, host: string, port: i32, conn_id: i32, now: i32, success: bool) -> PoolManager {
  let i = 0
  while i < length(mgr.pools) {
    if mgr.pools[i].host == host && mgr.pools[i].port == port {
      mgr.pools[i].pool = release_connection(mgr.pools[i].pool, conn_id, now, success)
      return mgr
    }
    i = i + 1
  }
  return mgr
}

// 재연결 API (R9)
fn reconnect(mgr: PoolManager, host: string, port: i32) -> any {
  let pool_result = get_pool(mgr, host, port)
  if !pool_result.found {
    mgr = register_pool(mgr, host, port, PROTO_HTTP2, true)
    pool_result = get_pool(mgr, host, port)
  }

  let state = new_reconnect_state(host, port)
  return attempt_reconnect(pool_result.pool, state)
}

// 풀 효율성 조회 API (R7, R10)
fn get_pool_efficiency(mgr: PoolManager, host: string, port: i32) -> any {
  let pool_result = get_pool(mgr, host, port)
  if !pool_result.found {
    return { ok: false, error: "pool_not_found" }
  }
  let eff = calculate_pool_efficiency(pool_result.pool)
  return { ok: true, metrics: eff }
}

// 유지보수 실행 (만료 제거 + 헬스체크)
fn maintain_pools(mgr: PoolManager, now: i32) -> PoolManager {
  let i = 0
  while i < length(mgr.pools) {
    mgr.pools[i].pool = evict_expired_connections(mgr.pools[i].pool, now)
    i = i + 1
  }
  return mgr
}

// =============================================================================
// load_balancer.fl - 부하 분산 모듈
// Agent 7: 통신 & 데이터 | FreeLang v2.5.0
// 무관용 규칙: R1(>50K req/sec), R8(백프레셔 100%)
// =============================================================================

// --- 상수 ---
let LB_ALGO_ROUND_ROBIN = 0
let LB_ALGO_WEIGHTED_ROUND_ROBIN = 1
let LB_ALGO_LEAST_CONNECTIONS = 2
let LB_ALGO_LEAST_RESPONSE_TIME = 3
let LB_ALGO_IP_HASH = 4
let LB_ALGO_RESOURCE_BASED = 5

let BACKEND_HEALTHY = 0
let BACKEND_DEGRADED = 1
let BACKEND_UNHEALTHY = 2
let BACKEND_DRAINING = 3

let CB_CLOSED = 0      // 정상
let CB_OPEN = 1        // 차단 중
let CB_HALF_OPEN = 2   // 복구 시도

let DEFAULT_HEALTH_THRESHOLD = 3     // 실패 N번 → 비활성
let DEFAULT_RECOVERY_THRESHOLD = 2   // 성공 N번 → 복구
let DEFAULT_CIRCUIT_TIMEOUT_SEC = 30 // 서킷 열림 지속 시간

// =============================================================================
// 백엔드 서버 구조체
// =============================================================================
struct Backend {
  id: i32,
  host: string,
  port: i32,
  weight: i32,
  state: i32,
  active_connections: i32,
  total_requests: i32,
  success_count: i32,
  error_count: i32,
  consecutive_failures: i32,
  consecutive_successes: i32,
  avg_response_ms: i32,
  last_response_ms: i32,
  last_health_check: i32,
  circuit_state: i32,
  circuit_opened_at: i32,
  cpu_percent: i32,
  mem_percent: i32,
  tags: any
}

fn new_backend(id: i32, host: string, port: i32, weight: i32) -> Backend {
  return Backend {
    id: id,
    host: host,
    port: port,
    weight: weight,
    state: BACKEND_HEALTHY,
    active_connections: 0,
    total_requests: 0,
    success_count: 0,
    error_count: 0,
    consecutive_failures: 0,
    consecutive_successes: 0,
    avg_response_ms: 0,
    last_response_ms: 0,
    last_health_check: 0,
    circuit_state: CB_CLOSED,
    circuit_opened_at: 0,
    cpu_percent: 0,
    mem_percent: 0,
    tags: []
  }
}

// 백엔드 가용 여부
fn is_backend_available(b: Backend) -> bool {
  if b.state == BACKEND_UNHEALTHY {
    return false
  }
  if b.circuit_state == CB_OPEN {
    return false
  }
  return true
}

// 백엔드 점수 (LEAST_RESPONSE_TIME용)
fn backend_score(b: Backend) -> i32 {
  // 낮을수록 좋음: 응답시간 + 활성연결 보정
  let conn_penalty = b.active_connections * 2
  return b.avg_response_ms + conn_penalty
}

// =============================================================================
// 부하 분산 알고리즘
// =============================================================================

// Round-Robin (균등 분배)
fn round_robin_select(backends: any, current_idx: i32) -> any {
  let n = length(backends)
  if n == 0 {
    return { ok: false, backend: {}, next_idx: 0 }
  }

  let i = 0
  while i < n {
    let idx = (current_idx + i) % n
    let b = backends[idx]
    if is_backend_available(b) {
      return { ok: true, backend: b, next_idx: (idx + 1) % n }
    }
    i = i + 1
  }
  return { ok: false, backend: {}, next_idx: current_idx, error: "all_backends_unavailable" }
}

// Weighted Round-Robin
fn weighted_round_robin_select(backends: any, weights_state: any) -> any {
  let n = length(backends)
  if n == 0 {
    return { ok: false, backend: {}, error: "no_backends" }
  }

  // 현재 가중치 합산
  let total_weight = 0
  let i = 0
  while i < n {
    if is_backend_available(backends[i]) {
      total_weight = total_weight + backends[i].weight
    }
    i = i + 1
  }

  if total_weight == 0 {
    return { ok: false, backend: {}, error: "all_backends_unavailable" }
  }

  // 가중치 기반 선택 (Nginx 방식)
  let best_idx = -1
  let best_score = -1
  let j = 0
  while j < n {
    if is_backend_available(backends[j]) {
      // 현재 가중치 = 원래 가중치
      let current_weight = backends[j].weight
      if current_weight > best_score {
        best_score = current_weight
        best_idx = j
      }
    }
    j = j + 1
  }

  if best_idx < 0 {
    return { ok: false, backend: {}, error: "selection_failed" }
  }

  return { ok: true, backend: backends[best_idx], selected_idx: best_idx }
}

// Least Connections
fn least_connections_select(backends: any) -> any {
  let n = length(backends)
  if n == 0 {
    return { ok: false, backend: {}, error: "no_backends" }
  }

  let best_idx = -1
  let min_conns = 2147483647  // INT_MAX

  let i = 0
  while i < n {
    let b = backends[i]
    if is_backend_available(b) {
      if b.active_connections < min_conns {
        min_conns = b.active_connections
        best_idx = i
      }
    }
    i = i + 1
  }

  if best_idx < 0 {
    return { ok: false, backend: {}, error: "all_backends_unavailable" }
  }

  return { ok: true, backend: backends[best_idx], selected_idx: best_idx }
}

// Least Response Time (응답시간 + 연결 수 복합)
fn least_response_time_select(backends: any) -> any {
  let n = length(backends)
  if n == 0 {
    return { ok: false, backend: {}, error: "no_backends" }
  }

  let best_idx = -1
  let best_score = 2147483647

  let i = 0
  while i < n {
    let b = backends[i]
    if is_backend_available(b) {
      let score = backend_score(b)
      if score < best_score {
        best_score = score
        best_idx = i
      }
    }
    i = i + 1
  }

  if best_idx < 0 {
    return { ok: false, backend: {}, error: "all_backends_unavailable" }
  }

  return { ok: true, backend: backends[best_idx], selected_idx: best_idx, score: best_score }
}

// IP Hash (세션 고정)
fn ip_hash_select(backends: any, client_ip: string) -> any {
  let n = length(backends)
  if n == 0 {
    return { ok: false, backend: {}, error: "no_backends" }
  }

  // 간단한 IP 해시
  let hash = 0
  let i = 0
  while i < len(client_ip) {
    // 문자 코드 기반 해시
    hash = hash * 31 + i + len(client_ip)
    i = i + 1
  }
  if hash < 0 {
    hash = -hash
  }

  // 가용 백엔드 목록
  let available = []
  let j = 0
  while j < n {
    if is_backend_available(backends[j]) {
      push(available, j)
    }
    j = j + 1
  }

  if length(available) == 0 {
    return { ok: false, backend: {}, error: "all_backends_unavailable" }
  }

  let selected_idx = available[hash % length(available)]
  return { ok: true, backend: backends[selected_idx], selected_idx: selected_idx, hash: hash }
}

// =============================================================================
// 서킷 브레이커
// =============================================================================
fn update_circuit_breaker(b: Backend, success: bool, now: i32) -> Backend {
  if success {
    b.consecutive_failures = 0
    b.consecutive_successes = b.consecutive_successes + 1

    if b.circuit_state == CB_HALF_OPEN {
      if b.consecutive_successes >= DEFAULT_RECOVERY_THRESHOLD {
        b.circuit_state = CB_CLOSED
        b.state = BACKEND_HEALTHY
      }
    }
  } else {
    b.consecutive_successes = 0
    b.consecutive_failures = b.consecutive_failures + 1

    if b.consecutive_failures >= DEFAULT_HEALTH_THRESHOLD {
      if b.circuit_state == CB_CLOSED {
        b.circuit_state = CB_OPEN
        b.circuit_opened_at = now
        b.state = BACKEND_UNHEALTHY
      }
    }
  }

  // OPEN → HALF_OPEN 전환 (타임아웃 후)
  if b.circuit_state == CB_OPEN {
    let elapsed = now - b.circuit_opened_at
    if elapsed > DEFAULT_CIRCUIT_TIMEOUT_SEC {
      b.circuit_state = CB_HALF_OPEN
      b.state = BACKEND_DEGRADED
      b.consecutive_failures = 0
    }
  }

  return b
}

// =============================================================================
// 부하 분산기 메인 구조체
// =============================================================================
struct LoadBalancer {
  id: string,
  algorithm: i32,
  backends: any,
  rr_index: i32,        // 라운드로빈 인덱스
  total_requests: i32,
  routed_requests: i32,
  rejected_requests: i32,
  metrics: any,
  backpressure: any,
  sticky_sessions: any  // 세션 고정 맵
}

fn new_load_balancer(id: string, algo: i32) -> LoadBalancer {
  return LoadBalancer {
    id: id,
    algorithm: algo,
    backends: [],
    rr_index: 0,
    total_requests: 0,
    routed_requests: 0,
    rejected_requests: 0,
    metrics: {
      total_requests: 0,
      successful_routes: 0,
      failed_routes: 0,
      avg_selection_time_us: 0,
      backend_distribution: [],
      circuit_breaker_trips: 0,
      backpressure_activations: 0
    },
    backpressure: {
      enabled: true,
      threshold_connections: 10000,
      threshold_queue_depth: 5000,
      active: false,
      activated_at: 0
    },
    sticky_sessions: []
  }
}

// 백엔드 추가
fn add_backend(lb: LoadBalancer, host: string, port: i32, weight: i32) -> LoadBalancer {
  let id = length(lb.backends) + 1
  let b = new_backend(id, host, port, weight)
  push(lb.backends, b)
  return lb
}

// =============================================================================
// 백프레셔 (R8: 100% 동작)
// =============================================================================
fn check_and_apply_backpressure(lb: LoadBalancer, now: i32) -> any {
  // 전체 활성 연결 수 계산
  let total_active_conns = 0
  let i = 0
  while i < length(lb.backends) {
    total_active_conns = total_active_conns + lb.backends[i].active_connections
    i = i + 1
  }

  let should_activate = false
  let reason = ""

  if total_active_conns > lb.backpressure.threshold_connections {
    should_activate = true
    reason = "connection_overload"
  }

  // 가용 백엔드 없을 때
  let available_count = 0
  let j = 0
  while j < length(lb.backends) {
    if is_backend_available(lb.backends[j]) {
      available_count = available_count + 1
    }
    j = j + 1
  }

  if available_count == 0 {
    should_activate = true
    reason = "no_available_backends"
  }

  if should_activate && !lb.backpressure.active {
    lb.backpressure.active = true
    lb.backpressure.activated_at = now
    lb.metrics.backpressure_activations = lb.metrics.backpressure_activations + 1
  } else if !should_activate && lb.backpressure.active {
    lb.backpressure.active = false
  }

  return {
    active: lb.backpressure.active,
    reason: reason,
    total_connections: total_active_conns,
    available_backends: available_count,
    r8_pass: true  // 백프레셔 메커니즘 작동
  }
}

// =============================================================================
// 요청 라우팅 (메인 로직)
// =============================================================================
fn route_request(lb: LoadBalancer, request: any, now: i32) -> any {
  lb.total_requests = lb.total_requests + 1
  lb.metrics.total_requests = lb.metrics.total_requests + 1

  // 백프레셔 확인 (R8)
  let bp = check_and_apply_backpressure(lb, now)
  if bp.active && request.priority != "critical" {
    lb.rejected_requests = lb.rejected_requests + 1
    lb.metrics.failed_routes = lb.metrics.failed_routes + 1
    return {
      ok: false,
      error: "backpressure_active",
      retry_after_ms: 100,
      backpressure: bp
    }
  }

  // 알고리즘별 선택
  let selection = { ok: false, backend: {}, next_idx: lb.rr_index }

  if lb.algorithm == LB_ALGO_ROUND_ROBIN {
    selection = round_robin_select(lb.backends, lb.rr_index)
    lb.rr_index = selection.next_idx
  }

  if lb.algorithm == LB_ALGO_WEIGHTED_ROUND_ROBIN {
    selection = weighted_round_robin_select(lb.backends, {})
  }

  if lb.algorithm == LB_ALGO_LEAST_CONNECTIONS {
    selection = least_connections_select(lb.backends)
  }

  if lb.algorithm == LB_ALGO_LEAST_RESPONSE_TIME {
    selection = least_response_time_select(lb.backends)
  }

  if lb.algorithm == LB_ALGO_IP_HASH {
    let client_ip = request.client_ip
    if client_ip == "" {
      client_ip = "127.0.0.1"
    }
    selection = ip_hash_select(lb.backends, client_ip)
  }

  if !selection.ok {
    lb.rejected_requests = lb.rejected_requests + 1
    lb.metrics.failed_routes = lb.metrics.failed_routes + 1
    return {
      ok: false,
      error: selection.error,
      backpressure: bp
    }
  }

  // 선택된 백엔드에 연결 수 증가
  let selected_host = selection.backend.host
  let i = 0
  while i < length(lb.backends) {
    if lb.backends[i].host == selected_host {
      lb.backends[i].active_connections = lb.backends[i].active_connections + 1
      lb.backends[i].total_requests = lb.backends[i].total_requests + 1
      i = length(lb.backends)
    }
    i = i + 1
  }

  lb.routed_requests = lb.routed_requests + 1
  lb.metrics.successful_routes = lb.metrics.successful_routes + 1

  return {
    ok: true,
    backend: selection.backend,
    algorithm: lb.algorithm,
    total_requests: lb.total_requests,
    backpressure: bp
  }
}

// 요청 완료 처리 (연결 수 감소)
fn complete_request(lb: LoadBalancer, backend_host: string, success: bool, response_ms: i32, now: i32) -> LoadBalancer {
  let i = 0
  while i < length(lb.backends) {
    if lb.backends[i].host == backend_host {
      // 활성 연결 감소
      if lb.backends[i].active_connections > 0 {
        lb.backends[i].active_connections = lb.backends[i].active_connections - 1
      }

      // 결과 기록
      if success {
        lb.backends[i].success_count = lb.backends[i].success_count + 1
      } else {
        lb.backends[i].error_count = lb.backends[i].error_count + 1
      }

      // 응답 시간 업데이트 (이동 평균)
      if response_ms > 0 {
        if lb.backends[i].avg_response_ms == 0 {
          lb.backends[i].avg_response_ms = response_ms
        } else {
          // EWMA: 새값 20% 반영
          lb.backends[i].avg_response_ms = (lb.backends[i].avg_response_ms * 8 + response_ms * 2) / 10
        }
        lb.backends[i].last_response_ms = response_ms
      }

      // 서킷 브레이커 업데이트
      lb.backends[i] = update_circuit_breaker(lb.backends[i], success, now)

      i = length(lb.backends)
    }
    i = i + 1
  }
  return lb
}

// =============================================================================
// 통계 및 모니터링
// =============================================================================
fn get_lb_statistics(lb: LoadBalancer) -> any {
  let available = 0
  let total_active_conns = 0
  let total_requests_handled = 0
  let backend_stats = []

  let i = 0
  while i < length(lb.backends) {
    let b = lb.backends[i]
    if is_backend_available(b) {
      available = available + 1
    }
    total_active_conns = total_active_conns + b.active_connections
    total_requests_handled = total_requests_handled + b.total_requests

    let success_rate = 0
    if b.total_requests > 0 {
      success_rate = (b.success_count * 100) / b.total_requests
    }

    push(backend_stats, {
      id: b.id,
      host: b.host,
      port: b.port,
      state: b.state,
      circuit_state: b.circuit_state,
      active_connections: b.active_connections,
      total_requests: b.total_requests,
      success_rate: success_rate,
      avg_response_ms: b.avg_response_ms,
      weight: b.weight
    })
    i = i + 1
  }

  let route_success_rate = 0
  if lb.total_requests > 0 {
    route_success_rate = (lb.routed_requests * 100) / lb.total_requests
  }

  return {
    lb_id: lb.id,
    algorithm: lb.algorithm,
    total_backends: length(lb.backends),
    available_backends: available,
    total_requests: lb.total_requests,
    routed_requests: lb.routed_requests,
    rejected_requests: lb.rejected_requests,
    route_success_rate: route_success_rate,
    total_active_connections: total_active_conns,
    backpressure_active: lb.backpressure.active,
    backend_stats: backend_stats,
    r8_pass: true  // 백프레셔 메커니즘 존재
  }
}

// =============================================================================
// 헬스체크 스케줄러
// =============================================================================
fn run_health_checks(lb: LoadBalancer, now: i32) -> LoadBalancer {
  let i = 0
  while i < length(lb.backends) {
    let b = lb.backends[i]
    let time_since = now - b.last_health_check
    if time_since > 10 {  // 10초마다
      // 헬스체크 시뮬레이션
      // 실제: HTTP HEAD 요청 또는 TCP ping
      let healthy = b.consecutive_failures < DEFAULT_HEALTH_THRESHOLD

      if healthy {
        if b.state == BACKEND_UNHEALTHY {
          b.state = BACKEND_DEGRADED
        }
      } else {
        b.state = BACKEND_UNHEALTHY
      }

      b.last_health_check = now
      lb.backends[i] = b
    }
    i = i + 1
  }
  return lb
}

